// Team popup
const popup = document.getElementById('teamPopup');
const popupClose = document.getElementById('popupClose');
let popupOpenScrollY = 0;
document.querySelectorAll('.team-card').forEach(card => {
  card.addEventListener('click', () => {
    const popupPhoto = document.getElementById('popupPhoto');
    if (card.dataset.photo) {
      popupPhoto.src = card.dataset.photo;
      popupPhoto.alt = card.dataset.name;
      popupPhoto.style.objectPosition = card.dataset.photoPosition || 'center top';
      popupPhoto.style.display = '';
    } else {
      popupPhoto.removeAttribute('src');
      popupPhoto.alt = '';
      popupPhoto.style.display = 'none';
    }
    document.getElementById('popupName').textContent = card.dataset.name;
    document.getElementById('popupRole').textContent = card.dataset.role;
    document.getElementById('popupBio').textContent = card.dataset.bio;
    popupOpenScrollY = window.scrollY;
    popup.classList.add('open');
  });
});
popupClose.addEventListener('click', () => popup.classList.remove('open'));
popup.addEventListener('click', (e) => { if (e.target === popup) popup.classList.remove('open'); });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') popup.classList.remove('open'); });
// Close the popup when the page scrolls; the 10px threshold ignores
// residual momentum-scroll events right after tapping a card open.
window.addEventListener('scroll', () => {
  if (popup.classList.contains('open') && Math.abs(window.scrollY - popupOpenScrollY) > 10) {
    popup.classList.remove('open');
  }
}, { passive: true });

// Hero scroll cue — hide once the page scrolls, reappear back at the hero
(function() {
  const cue = document.querySelector('.about-hero__scroll');
  if (!cue) return;
  const onScroll = () => {
    cue.style.opacity = window.scrollY > 40 ? '0' : '';
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
})();

// Image pop-out on scroll
(function() {
  const imgWrap = document.getElementById('storySlideshow');
  const story = imgWrap ? imgWrap.closest('.story') : null;
  if (!imgWrap || !story) return;
  window.addEventListener('scroll', () => {
    const rect = story.getBoundingClientRect();
    const inView = rect.top < window.innerHeight * 0.3 && rect.bottom > window.innerHeight * 0.3;
    imgWrap.classList.toggle('expanded', inView);
  }, { passive: true });
})();

// Values cycling card — auto-cycles, swipeable, dots tappable
(function() {
  const single = document.getElementById('valueSingle');
  const slides = document.querySelectorAll('.value-slide');
  const dots = document.querySelectorAll('.value-dot');
  let idx = 0, timer;
  function show(n) {
    slides[idx].classList.remove('active');
    dots[idx].classList.remove('active');
    idx = (n + slides.length) % slides.length;
    slides[idx].classList.add('active');
    dots[idx].classList.add('active');
  }
  function start() { timer = setInterval(() => show(idx + 1), 2800); }
  function restart() { clearInterval(timer); start(); }
  let startX = 0;
  single.addEventListener('touchstart', e => { startX = e.touches[0].clientX; }, { passive: true });
  single.addEventListener('touchend', e => {
    const dx = e.changedTouches[0].clientX - startX;
    if (Math.abs(dx) > 40) { show(idx + (dx < 0 ? 1 : -1)); restart(); }
  }, { passive: true });
  dots.forEach((dot, i) => dot.addEventListener('click', () => { show(i); restart(); }));
  start();
})();

// Scroll reveal — add .js so CSS animations activate
document.documentElement.classList.add('js');
const reveals = document.querySelectorAll('.reveal');
const observer = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.classList.add('visible');
      observer.unobserve(e.target);
    }
  });
}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
reveals.forEach(el => observer.observe(el));

// Story slideshow
(function() {
  const slides = document.querySelectorAll('#storySlideshow .story__slide');
  let idx = 0;
  setInterval(() => {
    slides[idx].classList.remove('active');
    idx = (idx + 1) % slides.length;
    slides[idx].classList.add('active');
  }, 3500);
})();

// Menu controls (hamburger click + close + backdrop)
(function() {
  const dropBtn = document.getElementById('dropdownBtn');
  const dropMenu = document.getElementById('dropdownMenu');
  const closeBtn = document.getElementById('menuCloseBtn');
  const backdrop = document.getElementById('navBackdrop');
  function open() { if (!dropMenu) return; dropMenu.classList.add('open'); if (dropBtn) { dropBtn.classList.add('active'); dropBtn.setAttribute('aria-expanded','true'); } }
  function close() { if (!dropMenu) return; dropMenu.classList.remove('open'); if (dropBtn) { dropBtn.classList.remove('active'); dropBtn.setAttribute('aria-expanded','false'); } }
  if (dropBtn) dropBtn.addEventListener('click', e => { e.stopPropagation(); dropMenu.classList.contains('open') ? close() : open(); });
  if (closeBtn) closeBtn.addEventListener('click', close);
  if (backdrop) backdrop.addEventListener('click', close);
  if (dropMenu) dropMenu.querySelectorAll('a').forEach(a => a.addEventListener('click', close));
  window.addEventListener('scroll', () => { if (window.scrollY > 20) close(); }, { passive: true });
})();
